#!/usr/bin/env bash
# One scripted session: owner env + KEY=VALUE lines, reach gameplay (nav.sh), then PROFILE=1: a
# simpleperf call-graph profile (10 s), else wait WAIT seconds; screenshot, thread dump into the
# log (where a hung game waits; DUMP_AT_END=0: none), stop, owner env back.
#   [PROFILE=1] [WAIT=60] [DUMP_AT_END=0] session.sh <dir> <tag> [KEY=VALUE ...]
# Do not edit this file (or nav.sh) while a session runs: bash reads on from its old offset.
# A game already running (the owner playing) is never touched.
set -euo pipefail
export MSYS_NO_PATHCONV=1
S=$(dirname "$0")
ADB=$(ls -d /c/Users/*/AppData/Local/Microsoft/WinGet/Packages/Google.PlatformTools_*/platform-tools | head -1)/adb.exe
DIR=$1; TAG=$2; shift 2
mkdir -p "$DIR"
if "$ADB" shell pidof dev.unchartedg2.game >/dev/null; then echo "$TAG: game already running - skipped"; exit 1; fi
{ cat "${OWNER_ENV:-$S/../env-g2.txt}"; for kv in "$@"; do echo "$kv"; done; } > "$DIR/env-$TAG.txt"
bash "$S/nav.sh" "$DIR/env-$TAG.txt" "$DIR/$TAG" > "$DIR/$TAG-nav.txt" 2>&1 || { echo "$TAG: nav failed"; exit 1; }
sleep 10
if [ "${PROFILE:-0}" = 1 ]; then
    bash "$S/../profile.sh" "$DIR/$TAG-prof" 10 "--call-graph fp ${PROF_EXTRA:-}" > "$DIR/$TAG-prof.txt" 2>&1 || true
else
    sleep "${WAIT:-60}"
fi
bash "$S/pad.sh" shot "$DIR/$TAG-end.png"
[ "${DUMP_AT_END:-1}" = 0 ] || bash "$S/pad.sh" dump
bash "$S/pad.sh" stop "$DIR/$TAG.log" "${OWNER_ENV:-$S/../env-g2.txt}" >/dev/null
echo "$TAG: $(python -I "$(cygpath -w "$S/absum.py")" "$DIR/$TAG.log")"
